const textState = arguments[0];
const data = this.obtainEscapeString(textState).split(',');
if (this instanceof Window_Message) {
    if (textState.drawing) {
        const filename = data[0].trim();
        const index = parseInt(data[1] || '0');
        $gameMessage.setFaceImage(filename, index);
        this.loadMessageFace();
        const rtl = $gameMessage.isRTL();
        const width = ImageManager.faceWidth;
        const height = this.innerHeight;
        const x = rtl ? this.innerWidth - width - 4 : 4;
        this.contents.clearRect(x, 0, width, height);
        this._faceBitmap.addLoadListener(this.drawMessageFace.bind(this));
    }
}

